add() {
  local a=$1
  local b=$2
  echo $((a + b))
}

result=$(add 3 5)
echo "Sum: $result"

factorial() {
  local n=$1
  if [ $n -le 1 ]; then
    echo 1
    return
  fi
  local prev=$(factorial $((n - 1)))
  echo $((n * prev))
}

echo $(factorial 5)

memoize() {
  local func=$1
  shift
  local key="$func:$*"

  if [ -n "${_memo_cache[$key]+_}" ]; then
    echo "${_memo_cache[$key]}"
    return
  fi

  local result=$($func "$@")
  _memo_cache[$key]=$result
  echo $result
}

declare -A _memo_cache
heavy_calc() { sleep 1; echo $(($1 * $1)); }
echo $(memoize heavy_calc 5)
echo $(memoize heavy_calc 5)

map() {
  local func=$1
  shift
  local result=()
  for item in "$@"; do
    result+=($($func $item))
  done
  echo "${result[@]}"
}

square() { echo $(($1 * $1)); }
echo $(map square 1 2 3 4 5)

filter() {
  local predicate=$1
  shift
  local result=()
  for item in "$@"; do
    if $predicate $item; then
      result+=($item)
    fi
  done
  echo "${result[@]}"
}

is_positive() { [ $1 -gt 0 ] && return 0 || return 1; }
echo $(filter is_positive -3 5 -1 7 2)

cache_result() {
  local cache_file="/tmp/cache_$1"
  if [ -f "$cache_file" ]; then
    cat "$cache_file"
    return
  fi
  local result=$("$@")
  echo "$result" > "$cache_file"
  echo "$result"
}

expensive_calc() { echo $(( $1 * $1 + $1 )); }
echo $(cache_result expensive_calc 42)

compose() {
  local funcs=("$@")
  echo "$(
    input=$(cat)
    for func in "${funcs[@]}"; do
      input=$(echo "$input" | $func)
    done
    echo "$input"
  )"
}

toupper() { tr '[:lower:]' '[:upper:]'; }
trim() { sed 's/^[[:space:]]*//;s/[[:space:]]*$//'; }

echo "  hello world  " | compose trim toupper
